import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, the committee fixes an exponent {exponent_a}. Determine the minimal positive integer n ≥ {lower_bound} for which there exists a bijection f: {1, ..., n} → {1, ..., n} satisfying both of the following for all x, y in {1, ..., n}: (i) If n divides {exponent_a}·x − y, then n+1 divides f(x)^{ {exponent_a} } − f(y). (ii) If n divides x + y, then n+1 divides f(x)·f(y) − 1. Find n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose a moderate lower bound to keep verification feasible
L = rng.randint(250, 1500)
# Choose exponent a, at least 3, and not too huge relative to L
a = rng.randint(3, max(4, min(L, 1000)))
# Occasionally bump L to ensure nontrivial next-prime search length
if rng.random() < 0.3:
    L += rng.randint(0, 50)
return {'lower_bound': L, 'exponent_a': a}

    def verifier(assign):
# Validate presence and types
if not isinstance(assign, dict):
    # Invalid assignment structure
    return (False, None)  # invalid
if 'lower_bound' not in assign or 'exponent_a' not in assign:
    return (False, None)
L = assign['lower_bound']
a = assign['exponent_a']
if not isinstance(L, int) or not isinstance(a, int):
    return (False, None)
if L < 2 or a < 2:
    return (False, None)

# Helper: primality test (deterministic trial division)
def is_prime(p):
    if p < 2:
        return False
    if p % 2 == 0:
        return p == 2
    d = 3
    while d * d <= p:
        if p % d == 0:
            return False
        d += 2
    return True

# Find minimal n >= L such that n+1 is prime
n = L
while True:
    if is_prime(n + 1):
        break
    n += 1
    # Safety cap to avoid pathological runtime
    if n - L > 100000:
        # Too large a gap to reasonably verify here
        return (False, None)

p = n + 1

# Factor p-1 = n to find a primitive root modulo p
def factorize(m):
    fac = {}
    x = m
    # Factor 2
    cnt = 0
    while x % 2 == 0:
        x //= 2
        cnt += 1
    if cnt:
        fac[2] = cnt
    f = 3
    while f * f <= x:
        c = 0
        while x % f == 0:
            x //= f
            c += 1
        if c:
            fac[f] = c
        f += 2
    if x > 1:
        fac[x] = 1
    return fac

fac = factorize(p - 1)
primes_of_n = list(fac.keys())

# Find primitive root g modulo p: g^((p-1)/q) != 1 for all prime divisors q of p-1
def primitive_root_mod_prime(p):
    if p == 2:
        return 1
    phi = p - 1
    fac = factorize(phi)
    for g in range(2, p):
        ok = True
        for q in fac.keys():
            if pow(g, phi // q, p) == 1:
                ok = False
                break
        if ok:
            return g
    return None

g = primitive_root_mod_prime(p)
if g is None:
    # Should not happen for prime p
    return (False, None)

# Define the candidate bijection f(x) = g^x mod p
# Check that it's a bijection from {1..n} to {1..n} (i.e., residues 1..p-1)
images = set()
for x in range(1, n + 1):
    images.add(pow(g, x, p))
if len(images) != n:
    return (False, None)

# Verify the two conditions for all x in 1..n using the induced y's
# Convention: represent residue 0 modulo n by n
def rep_mod_n(val):
    r = val % n
    return n if r == 0 else r

# Check condition (i): if n | a x - y (with canonical y), then p | f(x)^a - f(y)
for x in range(1, n + 1):
    y = rep_mod_n(a * x)
    fx = pow(g, x, p)
    fy = pow(g, y, p)
    if pow(fx, a, p) != fy:
        return (False, None)

# Check condition (ii): if n | x + y (i.e., y ≡ -x mod n), then p | f(x) f(y) - 1
for x in range(1, n + 1):
    y = rep_mod_n(-x)
    fx = pow(g, x, p)
    fy = pow(g, y, p)
    if (fx * fy) % p != 1:
        return (False, None)

# All checks passed; return the answer n
return (True, n)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

